def fmt_table(rows):
    header = rows[0]
    ncols = len(header)
    padded_rows = [row + [''] * (ncols - len(row)) for row in rows]

    widths = []
    for c in range(ncols):
        widths.append(max(len(row[c]) for row in padded_rows))

    def is_numeric(s):
        try:
            float(s)
            return True
        except ValueError:
            return False

    def border():
        return ''.join('+' + '-' * (w + 2) for w in widths) + '+'

    def content_line(row, is_header=False):
        cells = []
        for c in range(ncols):
            cell = row[c]
            w = widths[c]
            if is_header or not is_numeric(cell):
                cells.append(' ' + cell.ljust(w) + ' ')
            else:
                cells.append(' ' + cell.rjust(w) + ' ')
        return '|' + '|'.join(cells) + '|'

    lines = [border()]
    lines.append(content_line(header, is_header=True))
    lines.append(border())
    for row in padded_rows[1:]:
        lines.append(content_line(row))
    lines.append(border())

    return '\n'.join(lines)
